internal sealed class MenuNavigation {
 ushort previous;long next;bool armed;readonly System.Diagnostics.Stopwatch watch=System.Diagnostics.Stopwatch.StartNew();
 public void Reset(){armed=false;previous=0;}
 public ushort Sample(ushort buttons){buttons&=0xf00f;if(!armed){if(buttons==0)armed=true;return 0;}long now=watch.ElapsedMilliseconds;ushort pressed=(ushort)(buttons&~previous);if((buttons&15)!=0&&now>=next){pressed|=(ushort)(buttons&15);next=now+180;}else if((pressed&15)!=0)next=now+400;previous=buttons;return pressed;}
}
