 protected override CreateParams CreateParams {get{var p=base.CreateParams;p.ClassStyle|=0x20000;return p;}}
 void PlaceOnTv(){var screen=Screen.AllScreens.FirstOrDefault(s=>string.Equals(s.DeviceName,monitor,StringComparison.OrdinalIgnoreCase));if(screen==null){if(!preview)throw new InvalidOperationException("The TV is no longer connected. Restore desktop and reconnect it.");screen=Screen.PrimaryScreen;}int h=screen.Bounds.Height,w=screen.Bounds.Width;float size=Math.Min(w/860f,h/800f);size=Math.Max(.65f,Math.Min(2.5f,size));Size=new Size((int)(720*size),(int)(660*size));Location=new Point(screen.Bounds.Left+(w-Width)/2,screen.Bounds.Top+(h-Height)/2);}
 float UiScale {get{return ClientSize.Width/720f;}}
 Rectangle Rect(int x,int y,int w,int h){float s=UiScale;return new Rectangle((int)(x*s),(int)(y*s),(int)(w*s),(int)(h*s));}
 void TextAt(Graphics g,string text,int x,int y,int w,int h,int size,bool bold,Color color){using(var font=new Font("Segoe UI",size*UiScale, bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))TextRenderer.DrawText(g,text,font,Rect(x,y,w,h),color,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);}
