 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using(var pen=new Pen(Theme.Border,2*UiScale))g.DrawRectangle(pen,new Rectangle(1,1,Width-3,Height-3));if(logo!=null)g.DrawImage(logo,Rect(26,23,46,46));TextAt(g,"SteamCouch",86,20,500,32,25,true,Theme.Text);TextAt(g,page==0?"YOUR COUCH CONTROLS":page==1?"CHOOSE AUDIO OUTPUT":"CHOOSE RESOLUTION & REFRESH RATE",86,56,580,24,11,true,Theme.Accent);
 if(sleepPrompt){Box(g,Rect(26,113,668,347),true);TextAt(g,"Put your PC to sleep?",52,140,600,60,27,true,Theme.Text);TextAt(g,"Your desktop is restored first. Games are not force-closed.",52,220,600,58,17,false,Theme.Muted);TextAt(g,"A / Enter   Restore desktop and sleep",52,300,600,40,22,true,Theme.Accent);TextAt(g,"B / Esc       Cancel",52,355,600,40,20,false,Theme.Text);}
 else if(trial!=null){int remaining=Math.Max(0,(int)Math.Ceiling((trial.Deadline-DateTime.UtcNow).TotalSeconds));Box(g,Rect(26,113,668,347),true);TextAt(g,"Keep these display settings?",52,140,600,60,27,true,Theme.Text);TextAt(g,trial.Error??("Automatically reverting in "+remaining+" seconds"),52,220,600,44,20,false,Theme.Muted);TextAt(g,"A / Enter   Keep settings",52,300,600,40,22,true,Theme.Accent);TextAt(g,"B / Esc       Revert now",52,355,600,40,20,false,Theme.Text);}
 else if(page==0){string[] values={muted?"Muted · "+volume+"%":volume+"%",outputName,hdrSupported?(hdrOn?"On":"Off"):"Unavailable on this connection",currentMode,preview?"Off":WindowsVrr.Enabled?"On · restart game to apply":"Off · restart game to apply","Restore your normal setup","Confirm before sleeping"};for(int i=0;i<TileCount;i++){int x=26+(i%2)*344,y=108+(i/2)*TileStep;int tileWidth=i==6?668:324;Box(g,Rect(x,y,tileWidth,TileHeight),i==index);using(var f=new Font("Segoe MDL2 Assets",23*UiScale,FontStyle.Regular,GraphicsUnit.Pixel))TextRenderer.DrawText(g,glyphs[i],f,Rect(x+18,y+18,32,34),Theme.Accent,TextFormatFlags.VerticalCenter);TextAt(g,titles[i],x+61,y+15,249,31,17,true,Theme.Text);TextAt(g,values[i],x+18,y+(allowSleep?48:57),tileWidth-36,allowSleep?32:37,i==0?25:15,i==0,Theme.Muted);}TextAt(g,index==0?"Left / Right changes volume · X mutes":index==4?"Windows-wide option. Enable FreeSync/G-SYNC on your TV and GPU too.":"A / Enter to select",28,allowSleep?505:490,664,40,14,false,Theme.Muted);}
