 async Task RefreshValues(){if(loading)return;loading=true;try{if(preview){volume=65;currentMode="3840 × 2160 · 120 Hz";outputName="Living room TV";hdrSupported=true;hdrOn=true;muted=false;modes=new List<VideoMode>{new VideoMode{Width=3840,Height=2160,Frequency=120},new VideoMode{Width=3840,Height=2160,Frequency=60},new VideoMode{Width=2560,Height=1440,Frequency=120},new VideoMode{Width=1920,Height=1080,Frequency=120}};}else{var result=await Task.Run(()=>{var t=VideoNative.Target(monitor);var h=VideoNative.Hdr(t);var mode=VideoNative.Current(monitor);var displayModes=VideoNative.Modes(monitor);var audio=devices.Audio().Where(r=>r.Get("Device State")=="Active").ToList();int percent;bool mute;using(var v=new SessionVolume()){percent=v.Percent;mute=v.Muted;}return new {Target=t,Hdr=h,Mode=mode,Modes=displayModes,Audio=audio,Percent=percent,Mute=mute};});target=result.Target;hdrSupported=result.Hdr.Supported;hdrOn=result.Hdr.Enabled;currentMode=result.Mode.ToString();modes=result.Modes;outputs=result.Audio;volume=result.Percent;muted=result.Mute;var output=outputs.FirstOrDefault(r=>r.Get("Default Multimedia")=="Render");outputName=output==null?"Current playback output":output.Get("Name");}lastRead=DateTime.UtcNow;PlaceOnTv();}catch(Exception e){message=e.Message;Storage.Log(e.ToString());}finally{loading=false;Invalidate();}}
 async Task Action(Func<Task> action){if(loading)return;loading=true;Invalidate();try{if(preview){message="Preview only — no settings changed.";return;}await action();message="Updated for this TV session.";}catch(Exception e){message=e.Message;Storage.Log(e.ToString());}finally{loading=false;navigation.Reset();}await RefreshValues();}
 async Task ChangeMute(){await Action(()=>Task.Run(()=>{using(var v=new SessionVolume())v.Muted=!v.Muted;}));}
 async Task Horizontal(int step){if(trial!=null||sleepPrompt||loading)return;if(page!=0){Navigate(step);return;}if(index==0)await Action(()=>Task.Run(()=>{using(var v=new SessionVolume())v.Percent=v.Percent+5*step;}));else {index=(index+step+TileCount)%TileCount;Invalidate();}}
 void Navigate(int step){if(loading||trial!=null||sleepPrompt)return;if(page==0)index=Math.Max(0,Math.Min(TileCount-1,index+step));else choice=Math.Max(0,Math.Min(choices.Count-1,choice+Math.Sign(step)));Invalidate();}
 async Task SelectAction(){try{await SelectCore();}catch(Exception error){message=error.Message;Storage.Log(error.ToString());Invalidate();}}
 async Task SelectCore(){if(loading)return;if(sleepPrompt){sleepPrompt=false;if(preview){message="Preview only — your PC will not sleep.";Invalidate();return;}if(!allowSleep||sleep==null)return;restoring=true;Close();await sleep();return;}if(trial!=null){bool kept=trial.Confirm();if(profileTrial){if(!kept)GameProfiles.ClearRejected();profileTrial=false;}trial=null;message=kept?"Display settings kept for this TV session.":"Confirmation expired. Previous settings restored.";await RefreshValues();return;}if(page==1){if(choice<0||choice>=outputs.Count)return;string id=outputs[choice].Get("Item ID");await Action(()=>Task.Run(()=>{for(int role=0;role<3;role++)devices.SetAudio(id,role);if(!Engine.Defaults(devices.Audio()).All(v=>v==id))throw new InvalidOperationException("Windows did not switch the audio output.");}));page=0;index=1;Invalidate();return;}if(page==2){if(choice<0||choice>=modes.Count)return;var mode=modes[choice];await BeginTrial(mode,null);return;}if(index==0){await ChangeMute();return;}if(index==1){page=1;choices=outputs.Select(r=>r.Get("Name")+" · "+r.Get("Device Name")).ToList();choice=Math.Max(0,outputs.FindIndex(r=>r.Get("Default Multimedia")=="Render"));}else if(index==2){if(!hdrSupported){message="HDR requires a supported TV, GPU and connection.";}else await BeginTrial(new VideoMode(),!hdrOn);}else if(index==3){page=2;choices=modes.Select(m=>m.ToString()).ToList();choice=Math.Max(0,modes.FindIndex(m=>m.ToString()==currentMode));}else if(index==4){await Action(()=>Task.Run(()=>VideoSession.SetVrr(!WindowsVrr.Enabled)));message="Windows VRR preference saved. Restart the game to apply it.";}else if(index==5){if(preview){message="Preview only — your desktop is unchanged.";}else{restoring=true;Close();await desktop();}}else if(index==6&&allowSleep){RequestSleep();}Invalidate();}
 async Task BeginTrial(VideoMode mode,bool? hdr){if(preview){message="Preview only — no display changes.";Invalidate();return;}loading=true;try{trial=await Task.Run(()=>new VideoTrial(target,mode,hdr));page=0;navigation.Reset();message="Confirm the change, or it will revert automatically.";PlaceOnTv();}catch(Exception e){message=e.Message;Storage.Log(e.ToString());}finally{loading=false;Invalidate();}}
 void Back(){if(loading)return;if(sleepPrompt){sleepPrompt=false;navigation.Reset();Invalidate();return;}if(trial!=null){try{trial.Revert();trial=null;if(profileTrial){GameProfiles.ClearRejected();profileTrial=false;}message="Previous settings restored.";}catch(Exception e){message=e.Message;}}else if(page!=0)page=0;else Close();navigation.Reset();Invalidate();}
 protected override bool ProcessCmdKey(ref Message msg,Keys key){switch(key&Keys.KeyCode){case Keys.Escape:Back();return true;case Keys.Enter:SelectAction().ContinueWith(t=>{if(t.IsFaulted)Storage.Log(t.Exception.ToString());});return true;case Keys.Up:Navigate(-2);return true;case Keys.Down:Navigate(2);return true;case Keys.Left:Horizontal(-1).ContinueWith(t=>{if(t.IsFaulted)Storage.Log(t.Exception.ToString());});return true;case Keys.Right:Horizontal(1).ContinueWith(t=>{if(t.IsFaulted)Storage.Log(t.Exception.ToString());});return true;}return base.ProcessCmdKey(ref msg,key);}
 protected override async void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(loading)return;float x=e.X/UiScale,y=e.Y/UiScale;if(trial!=null||sleepPrompt){if(y>=290&&y<=345)await SelectAction();else if(y>=345&&y<=410)Back();return;}if(page==0){for(int i=0;i<TileCount;i++)if(Rect(26+(i%2)*344,108+(i/2)*TileStep,i==6?668:324,TileHeight).Contains(e.Location)){index=i;await SelectAction();return;}}else{int start=Math.Max(0,Math.Min(choice-3,choices.Count-6));for(int row=0;row<Math.Min(6,choices.Count);row++)if(Rect(26,108+row*64,668,55).Contains(e.Location)){choice=start+row;await SelectAction();return;}}if(y>=607)Back();Invalidate();}
 protected override async void OnMouseWheel(MouseEventArgs e){base.OnMouseWheel(e);if(page==0&&index==0)await Horizontal(Math.Sign(e.Delta));else Navigate(-Math.Sign(e.Delta));}
  public void RequestSleep(){if(!allowSleep||loading||trial!=null)return;sleepPrompt=true;navigation.Reset();Invalidate();}
 public async Task ApplyProfile(GameProfile profile){if(loading||trial!=null)return;loading=true;profileTrial=true;try{trial=await GameProfiles.Begin(monitor,profile);message="Game profile: "+profile.Name;page=0;navigation.Reset();PlaceOnTv();}catch(Exception error){GameProfiles.ClearRejected();profileTrial=false;message=error.Message;Storage.Log(error.ToString());}finally{loading=false;Invalidate();}}
